import{_ as n,o as t,c as i,ae as r}from"./chunks/framework.BvHJbMD4.js";const c=JSON.parse('{"title":"Drehbuch-Update: Szene 42 - Die Ästhetik der Kleinigkeit","description":"","frontmatter":{},"headers":[],"relativePath":"logbuch/szene-aesthetik-der-kleinigkeit.md","filePath":"logbuch/szene-aesthetik-der-kleinigkeit.md"}'),s={name:"logbuch/szene-aesthetik-der-kleinigkeit.md"};function a(o,e,h,d,g,l){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="drehbuch-update-szene-42-die-asthetik-der-kleinigkeit" tabindex="-1">Drehbuch-Update: Szene 42 - Die Ästhetik der Kleinigkeit <a class="header-anchor" href="#drehbuch-update-szene-42-die-asthetik-der-kleinigkeit" aria-label="Permalink to &quot;Drehbuch-Update: Szene 42 - Die Ästhetik der Kleinigkeit&quot;">​</a></h1><p><strong>STIL:</strong> Eine hektische Pressekonferenz. Überbelichtete Gesichter, das Blitzlichtgewitter der Fotografen wirkt wie ein Stroboskop. Mikrofone ragen wie schwarze Lanzen ins Bild.</p><p><strong>BESETZUNG:</strong></p><ul><li><strong>Minister Dr. Gernot Gönner:</strong> Ein Schauspieler mit perfekt gegeltem Haar und einem Lächeln, das so fest sitzt wie seine Krawatte.</li><li><strong>Journalisten:</strong> Ein Chor aus kritischen Stimmen aus dem Off.</li></ul><hr><p><strong>INT. PRESSEZENTRUM - TAG</strong></p><p>Minister Gönner steht am Pult. Er wirkt nicht ertappt, sondern eher... akademisch beleidigt.</p><p><strong>JOURNALIST (OFF)</strong> Herr Minister, die Liste der Spenden von Frau Horten ist fast drei Meter lang. Alles Beträge knapp unter der Meldegrenze. Das kann doch kein Zufall sein!</p><p><strong>GÖNNER</strong> (atmet tief ein, lächelt mitleidig) Wissen Sie, was das Problem der heutigen Zeit ist? Ein eklatanter Mangel an Sinn für Ästhetik. Sie sehen eine Liste von Zahlen. Ich sehe ein Kunstwerk.</p><p>Er macht eine raumgreifende Geste mit den Händen.</p><p><strong>GÖNNER</strong> Frau Horten ist eine Mäzenin des Pointillismus. Sie kennen Seurat? Signac? Diese großen Geister haben verstanden, dass die Wahrheit nicht im großen, groben Pinselstrich liegt. Die Wahrheit setzt sich aus tausenden, winzigen, leuchtenden Punkten zusammen.</p><p><strong>JOURNALIST (OFF)</strong> Wir reden hier über 49.000-Euro-Häppchen am Rechnungshof vorbei!</p><p><strong>GÖNNER</strong> (unterbricht ihn sanft) Ich rede über die Freiheit der Kunst! Wenn eine Dame von Welt sich entscheidet, ihre Zuneigung zur Demokratie in vielen kleinen, zärtlichen Gesten auszudrücken – wer sind wir, dass wir ihr ein grobes, bürokratisches Raster aufzwingen?</p><p>Er beugt sich vertraulich zum Mikrofon.</p><p><strong>GÖNNER</strong> Ein Berg besteht aus Sandkörnern. Würden Sie ein Sandkorn beim Zoll anmelden? Nein. Erst wenn es ein Berg ist. Aber für uns... für uns ist es ein Strand. Und auf einem Strand lässt es sich eben besser regieren.</p><p><strong>JOURNALIST (OFF)</strong> Das ist doch reine Spendenstückelung zur Umgehung der Transparenz!</p><p><strong>GÖNNER</strong> (rückt seine Krawatte zurecht) Transparenz ist ein schönes Wort. Aber Glas ist auch transparent, und trotzdem rennen ständig Leute dagegen. Wir bevorzugen das sanfte Licht der Diskretion. Das ist keine Umgehung, das ist... politische Landschaftspflege.</p><p><strong>FADE TO BLACK.</strong></p>',18)])])}const p=n(s,[["render",a]]);export{c as __pageData,p as default};
